import { desc, eq, sql } from 'drizzle-orm';
import { z } from 'zod';
import { db } from '../db/index.js';
import { documents, numberSequences } from '../db/schema.js';
import { writeAudit } from '../audit.js';
import { authorize } from '../security.js';
import { createDocumentPdf } from '../services/pdf.js';
import { signedDownload, uploadObject } from '../services/storage.js';
async function nextNumber(type) { const year = new Date().getUTCFullYear(); const [row] = await db.insert(numberSequences).values({ type, year, value: 1 }).onConflictDoUpdate({ target: [numberSequences.type, numberSequences.year], set: { value: sql `${numberSequences.value}+1` } }).returning(); return `${type}-${year}-${String(row.value).padStart(4, '0')}`; }
const routes = async (app) => {
    app.post('/documents/upload', { preHandler: authorize(app, 'documents', 'create') }, async (request, reply) => { const input = z.object({ entityType: z.string().min(1), entityId: z.string().uuid(), type: z.string().min(1), filename: z.string().min(1), mimeType: z.string().min(1), contentBase64: z.string().min(1), expiresAt: z.coerce.date().optional() }).parse(request.body), body = Buffer.from(input.contentBase64, 'base64'); if (body.length > 15 * 1024 * 1024)
        throw Object.assign(new Error('FILE_TOO_LARGE'), { statusCode: 413 }); const [latest] = await db.select({ version: documents.version }).from(documents).where(eq(documents.entityId, input.entityId)).orderBy(desc(documents.version)).limit(1), version = (latest?.version ?? 0) + 1, key = `${input.entityType}/${input.entityId}/${input.type}/v${version}-${input.filename}`; await uploadObject(key, body, input.mimeType); const [record] = await db.insert(documents).values({ entityType: input.entityType, entityId: input.entityId, type: input.type, version, objectKey: key, mimeType: input.mimeType, size: body.length, expiresAt: input.expiresAt, uploadedBy: request.user.sub }).returning(); await writeAudit(request, { action: 'UPLOAD', entity: 'document', entityId: record.id, after: record }); return reply.code(201).send(record); });
    app.post('/documents/generate', { preHandler: authorize(app, 'documents', 'create') }, async (request, reply) => { const input = z.object({ entityType: z.string(), entityId: z.string().uuid(), type: z.enum(['DO', 'GP', 'EP', 'GTN', 'PL', 'CI']), shipmentReference: z.string().optional(), fields: z.record(z.string(), z.string()) }).parse(request.body), number = await nextNumber(input.type), pdf = await createDocumentPdf({ number, type: input.type, date: new Date().toISOString(), shipmentReference: input.shipmentReference, fields: input.fields }), key = `generated/${input.type}/${number}.pdf`; await uploadObject(key, pdf, 'application/pdf'); const [record] = await db.insert(documents).values({ entityType: input.entityType, entityId: input.entityId, type: input.type, number, objectKey: key, mimeType: 'application/pdf', size: pdf.length, uploadedBy: request.user.sub }).returning(); await writeAudit(request, { action: 'GENERATE', entity: 'document', entityId: record.id, after: record }); return reply.code(201).send(record); });
    app.get('/documents/:id/download', { preHandler: authorize(app, 'documents', 'view') }, async (request) => { const { id } = z.object({ id: z.string().uuid() }).parse(request.params), [record] = await db.select().from(documents).where(eq(documents.id, id)).limit(1); if (!record)
        throw Object.assign(new Error('DOCUMENT_NOT_FOUND'), { statusCode: 404 }); return { url: await signedDownload(record.objectKey), expiresIn: 300 }; });
};
export default routes;
